### 3. Creating `script.js` (The Interactive Sketch)

I will create a particle system where circles appear and grow/change color based on the distance to the mouse cursor.

```javascript
write('script.js', `
let particles = [];
const NUM_PARTICLES = 50;

// Particle class definition
class Particle {
    constructor(x, y) {
        this.position = createVector(x, y);
        this.velocity = p5.Vector.random2D();
        this.velocity.mult(random(0.5, 2));
        this.radius = random(3, 10);
        this.lifespan = 255;
    }

    update() {
        // Move towards the mouse position (attraction force)
        let mouseVector = createVector(mouseX, mouseY);
        let directionToMouse = p5.Vector.sub(mouseVector, this.position);
        let distance = directionToMouse.mag();

        // Apply a slight pull towards the mouse, inversely proportional to distance
        let force = p5.Vector.div(directionToMouse, distance);
        force.mult(0.005); // Tuning factor

        this.velocity.add(force);
        this.velocity.limit(5); // Keep speed reasonable

        this.position.add(this.velocity);

        // Fade out slightly over time
        this.lifespan -= 1;
    }

    display() {
        stroke(255, 150, 0, this.lifespan);
        strokeWeight(this.radius);
        noFill();
        ellipse(this.position.x, this.position.y, this.radius * 2);
    }
}

function setup() {
    // Fullscreen canvas setup is handled by the HTML/CSS structure, 
    // but we ensure p5.setup runs correctly.
    createCanvas(windowWidth, windowHeight);

    // Initialize particles spread across the screen
    for (let i = 0; i < NUM_PARTICLES; i++) {
        let x = random(width);
        let y = random(height);
        particles.push(new Particle(x, y));
    }

    background(10, 10, 50); // Dark blue background
}

function draw() {
    // Creating a slight fade effect on the background each frame instead of clearing completely
    background(10, 10, 50, 30); 

    // Update and display all particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.update();
        p.display();

        // Remove particles that have faded away
        if (p.lifespan < 0) {
            particles.splice(i, 1);
        }
    }

    // Add a small particle burst directly at the mouse location for more immediate feedback
    if (frameCount % 3 === 0) {
        particles.push(new Particle(mouseX, mouseY));
    }
}

function mouseMoved() {
    // On mouse move, we just let the particles react naturally.
    // The attraction force in update() handles the core interaction.
}

function mouseDragged() {
    // When dragging, we can create more immediate feedback, like a temporary trail.
    // The existing particle logic handles this well enough, but we can ensure
    // a fresh particle is spawned slightly more aggressively here if desired.
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
    // Re-initialize particles if needed, or just let them adjust their physics.
}
`);
```

