    // Dibuja la partícula
    display() {
        stroke(255, 150, 0, this.lifespan); // Color naranja brillante, con opacidad
        strokeWeight(this.radius);
        point(this.historyX, this.historyY);
    }
}

// Función que se ejecuta al iniciar la sketch
function setup() {
    // p5.js detectará el tamaño del body, forzando el fullscreen
